export const sep = '/';
export const delimiter = ';';

function platform() {
    if (globalThis.process && globalThis.process.platform) return String(globalThis.process.platform);
    return String(globalThis.__MOCHI_PLATFORM__ || 'win32');
}

export function cwd() {
    if (globalThis.process && typeof globalThis.process.cwd === 'function') return globalThis.process.cwd();
    return String(globalThis.__MOCHI_CWD__ || '.');
}

function clean(input) {
    return String(input ?? '').replace(/\\/g, '/');
}

function stripTrailing(value) {
    return value.replace(/\/+$/, '');
}

export function normalize(input) {
    const raw = clean(input);
    if (!raw) return '.';
    const absolute = /^([A-Za-z]:)?\//.test(raw);
    const prefix = absolute ? (raw.match(/^[A-Za-z]:/) ? raw.slice(0, 2) : '') : '';
    const body = absolute ? raw.slice(prefix.length) : raw;
    const parts = [];
    for (const part of body.split('/')) {
        if (!part || part === '.') continue;
        if (part === '..') {
            if (parts.length && parts[parts.length - 1] !== '..') parts.pop();
            else if (!absolute) parts.push('..');
            continue;
        }
        parts.push(part);
    }
    let out = prefix + (absolute ? '/' : '') + parts.join('/');
    if (!out && prefix) out = prefix + '/';
    if (!out) out = '.';
    return out;
}

export function join(...parts) {
    const list = [];
    for (const part of parts) {
        const value = clean(part);
        if (!value) continue;
        if (list.length === 0) list.push(value);
        else list.push(value.replace(/^\/+/, ''));
    }
    if (!list.length) return '.';
    return normalize(list.join('/'));
}

export function resolve(...parts) {
    let base = '';
    if (!parts.length) return normalize(cwd());
    const first = clean(parts[0]);
    if (/^([A-Za-z]:)?\//.test(first)) base = first;
    else base = join(cwd(), first);
    for (let i = 1; i < parts.length; i++) base = join(base, parts[i]);
    return normalize(base);
}

export function isAbsolute(input) {
    return /^([A-Za-z]:)?\//.test(clean(input));
}

export function dirname(input) {
    const value = stripTrailing(normalize(input));
    const slash = value.lastIndexOf('/');
    if (slash < 0) return '.';
    if (slash === 0) return '/';
    if (slash === 2 && /^[A-Za-z]:/.test(value)) return value.slice(0, 3);
    return value.slice(0, slash);
}

export function basename(input, suffix = '') {
    let value = stripTrailing(normalize(input));
    const slash = value.lastIndexOf('/');
    if (slash >= 0) value = value.slice(slash + 1);
    const ext = String(suffix ?? '');
    if (ext && value.endsWith(ext)) value = value.slice(0, -ext.length);
    return value;
}

export function extname(input) {
    const value = basename(input);
    const dot = value.lastIndexOf('.');
    return dot <= 0 ? '' : value.slice(dot);
}

export function relative(from, to) {
    const a = normalize(resolve(from)).split('/').filter(Boolean);
    const b = normalize(resolve(to)).split('/').filter(Boolean);
    let i = 0;
    while (i < a.length && i < b.length && a[i] === b[i]) i++;
    const out = [];
    for (let j = i; j < a.length; j++) out.push('..');
    for (let j = i; j < b.length; j++) out.push(b[j]);
    return out.join('/') || '.';
}

export function toNamespacedPath(input) {
    return normalize(input);
}

export function parse(input) {
    const value = normalize(input);
    const root = value.match(/^[A-Za-z]:\//) ? value.slice(0, 3) : (value.startsWith('/') ? '/' : '');
    const base = basename(value);
    const ext = extname(base);
    return {
        root,
        dir: dirname(value),
        base,
        ext,
        name: ext ? base.slice(0, -ext.length) : base,
    };
}

export function format(parts = {}) {
    const dir = parts.dir || parts.root || '';
    const name = parts.name || '';
    const ext = parts.ext || '';
    return normalize(`${dir}/${name}${ext}`);
}

export const posix = {
    sep,
    delimiter: ':',
    normalize,
    join,
    resolve,
    isAbsolute,
    dirname,
    basename,
    extname,
    relative,
    toNamespacedPath,
    parse,
    format,
    cwd,
};

export const win32 = {
    sep,
    delimiter,
    normalize,
    join,
    resolve,
    isAbsolute,
    dirname,
    basename,
    extname,
    relative,
    toNamespacedPath,
    parse,
    format,
    cwd,
};

export default {
    sep,
    delimiter,
    platform: platform(),
    normalize,
    join,
    resolve,
    isAbsolute,
    dirname,
    basename,
    extname,
    relative,
    toNamespacedPath,
    parse,
    format,
    cwd,
    posix,
    win32,
};
